input.command:
python3 - <<'EOF'
s=open('index.html').read()
t='''<script>
window.onerror=function(m){document.body.setAttribute("data-err",m)};
setTimeout(function(){
 var out=[];
 document.querySelector('[data-view="online"]').click();
 var hit=document.querySelector('#revChart svg rect:last-of-type'), r=hit.getBoundingClientRect();
 hit.dispatchEvent(new PointerEvent("pointermove",{clientX:r.left+r.width*0.95,clientY:r.top+50,bubbles:true,pointerType:"mouse"}));
 out.push("tip:"+document.getElementById("tooltip").textContent+"|"+document.getElementById("tooltip").className);
 document.querySelector('th[data-key="change"] .sort-btn').click();
 out.push("sort1:"+[].map.call(document.querySelectorAll("#cafeBody strong"),function(e){return e.textContent}).join(","));
 document.querySelector('th[data-key="name"] .sort-btn').click();
 out.push("sort2:"+[].map.call(document.querySelectorAll("#cafeBody strong"),function(e){return e.textContent}).join(",")+" aria="+document.querySelector('th[data-key="name"]').getAttribute("aria-sort"));
 var sI=document.getElementById("search"); sI.value="online"; sI.dispatchEvent(new Event("input"));
 out.push("search:"+document.getElementById("searchStatus").textContent);
 document.getElementById("menuBtn").click();
 out.push("nav:"+document.getElementById("menuBtn").getAttribute("aria-expanded"));
 out.push("err:"+(document.body.getAttribute("data-err")||"none"));
 var p=document.createElement("pre");p.id="OUT";p.textContent=out.join("\\n");document.body.appendChild(p);
},300);
</script></body>'''
open('/tmp/kk/test.html','w').write(s.replace('</body>',t))
EOF
